            "第三步：得交點之 $x$ 坐標為 $x = -2$ 與 $x = 1$，此即為積分區間 $[-2, 1]$",
            "第四步：在區間 $[-2, 1]$ 內，拋物線在上方（如 $x = 0$ 時 $4 > 2$），故上曲線減下曲線為：$(4 - x^2) - (x + 2) = 2 - x - x^2$",
            "第五步：列出定積分：$A = \\int_{-2}^1 (2 - x - x^2) \\, dx$",
            "第六步：求反導函數：$\\left[ 2x - \\frac{x^2}{2} - \\frac{x^3}{3} \\right]_{-2}^1$",
            "第七步：代入上限 $x = 1$：$2(1) - \\frac{1^2}{2} - \\frac{1^3}{3} = 2 - \\frac{1}{2} - \\frac{1}{3} = \\frac{12 - 3 - 2}{6} = \\frac{7}{6}$",
