      "coreConcepts": [
        "【細胞結構】",
        "1. 細胞核：生命中樞，含DNA。",
        "2. 細胞膜：控制物質進出 (脂質雙層)。",
        "3. 粒線體：細胞的發電廠，進行有氧呼吸產生能量 (ATP)。",
        "4. 液胞：儲存水分廢物。植物液胞大而明顯。",
        "5. 細胞壁：植物獨有 (纖維素組成)，提供支持保護，但無法控制物質進出。",
        "6. 葉綠體：植物獨有，進行光合作用。",
        "【物質進出細胞】",
        "• 擴散作用：小分子(氧氣、二氧化碳)由高濃度往低濃度移動。",
        "• 滲透作用：專指水分子的擴散。若放入濃鹽水(高張溶液)，細胞會失水萎縮；若放入清水(低張溶液)，動物細胞會脹破，植物細胞則因細胞壁保護而膨脹不破裂。"
      ],
